import type { BankItem, Difficulty } from './types';

/**
 * More grade 3-5 word-meaning items (synonyms, antonyms, vocabulary and
 * context clues), added so these topics repeat less often. Same rules and
 * topic keys as readingBank.ts. Every prompt here is unique across the
 * combined bank (see readingBankMoreVocab.test.ts).
 * Massachusetts 2017 ELA framework: L.3.4-L.5.4 (context clues) and
 * L.3.5-L.5.5 (word relationships).
 */
function q(
  topic: string,
  difficulty: Difficulty,
  prompt: string,
  answer: string,
  wrong: string[],
  explanation: string,
): BankItem {
  return { topic, difficulty, prompt, answer, wrong, explanation };
}

